INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7656319, 1246988, 15511, '<td valign="top">Unfortunate that the sky is largely without color, as this would have balanced the photo a bit more.</td>', 'Unfortunate that the sky is largely without color, as this would have balanced the photo a bit more.', '2020-03-25 00:12:44.000000', NULL, 1),
(7656320, 1246694, 15511, '<td valign="top">It''s good how you captured the consistency of the ripples in the water. This image might have been just as interesting with only the water surface shown and rotated around.</td>', 'It''s good how you captured the consistency of the ripples in the water. This image might have been just as interesting with only the water surface shown and rotated around.', '2020-03-25 00:16:36.000000', NULL, 1),
(7656321, 1246991, 15511, '<td valign="top">Unfortunate that the image wasn''t rotated before submission. The lighting on the tress and branches is very nice.</td>', 'Unfortunate that the image wasn''t rotated before submission. The lighting on the tress and branches is very nice.', '2020-03-25 00:18:47.000000', NULL, 1),
(7656323, 1246991, 114285, '<td valign="top">Im not sure why you didnt shoot this in landscape mode or even rotate it maybe the site cancel can rotate it for you.<br/> <br/>Anyway to be brutally honest there doesnt really seem to be a focal point. The chair in the foreground doesnt really add to the image, and the homes in the background lack appeal. I realise maybe you are in lockdown, but Im pretty sure you couldve come up with something better :-)</td>', 'Im not sure why you didnt shoot this in landscape mode or even rotate it maybe the site cancel can rotate it for you. Anyway to be brutally honest there doesnt really seem to be a focal point. The chair in the foreground doesnt really add to the image, and the homes in the background lack appeal. I realise maybe you are in lockdown, but Im pretty sure you couldve come up with something better :-)', '2020-03-25 00:25:35.000000', NULL, 1),
(7656324, 1246986, 15511, '<td valign="top">"Bleak and Unforgiving" is right. Although the clouds have shape and texture, you didn''t accentuate that. Having something in focus may have created more interest.</td>', '"Bleak and Unforgiving" is right. Although the clouds have shape and texture, you didn''t accentuate that. Having something in focus may have created more interest.', '2020-03-25 00:26:38.000000', NULL, 1),
(7656325, 1246986, 114285, '<td valign="top">Very mundane suburban image, Im pretty sure if you drove around you couldve found something better since it looks like it has been snowing. Also seems to lack clarity and seems a little bit too contrasty for my liking.<br/> <br/>Horizon needs to be straightened and there is colour noise in the sky. I see you took this towards sunset that is a positive.<br/> <br/>I hope with his critique you can move on forward and produce a finer Image.<br/>I really do hope that I have not offended you with my comments  but I remember when I started here I received a lot of harsh comments...but at the end of the day if I didnt listen and change I never wouldve achieved what I have at present.<br/> <br/>All the best.</td>', 'Very mundane suburban image, Im pretty sure if you drove around you couldve found something better since it looks like it has been snowing. Also seems to lack clarity and seems a little bit too contrasty for my liking. Horizon needs to be straightened and there is colour noise in the sky. I see you took this towards sunset that is a positive. I hope with his critique you can move on forward and produce a finer Image.I really do hope that I have not offended you with my comments  but I remember when I started here I received a lot of harsh comments...but at the end of the day if I didnt listen and change I never wouldve achieved what I have at present. All the best.', '2020-03-25 00:30:41.000000', NULL, 1),
(7656326, 1246892, 114285, '<td valign="top">I really love that sky and those clouds are magnificent. It seems a little bit too contrasty for my liking though, maybe adjusting the highlights wouldve enhanced the shrubs at the front or maybe thats how you liked it who knows. There also doesnt seem to be a lot of clarity in the background.<br/> <br/>Taken towards sunset or sunrise who knows that is a positive. Anyway pretty sure this is the red.</td>', 'I really love that sky and those clouds are magnificent. It seems a little bit too contrasty for my liking though, maybe adjusting the highlights wouldve enhanced the shrubs at the front or maybe thats how you liked it who knows. There also doesnt seem to be a lot of clarity in the background. Taken towards sunset or sunrise who knows that is a positive. Anyway pretty sure this is the red.', '2020-03-25 00:33:19.000000', NULL, 1),
(7656327, 1246988, 114285, '<td valign="top">Seems to be a strange mix of photos in this small pond of entries. Im just wondering even during lockdown you can travel around in your car and scope a better scene.  I can only see a hint of blue sky to the right, the centre of the photo is completely blown out. Looks like you took this during the day, try taking the photo during the golden hour next time. Also a little bit on the soft side, needs a little sharpening and the colours are little bit flat. Thats a pretty pond to have near your library though :)</td>', 'Seems to be a strange mix of photos in this small pond of entries. Im just wondering even during lockdown you can travel around in your car and scope a better scene.  I can only see a hint of blue sky to the right, the centre of the photo is completely blown out. Looks like you took this during the day, try taking the photo during the golden hour next time. Also a little bit on the soft side, needs a little sharpening and the colours are little bit flat. Thats a pretty pond to have near your library though :)', '2020-03-25 00:37:01.000000', NULL, 1),
(7656328, 1246694, 114285, '<td valign="top">I always love reflections in the water especially of trees. Great job on seeing the beauty in the water.<br/> <br/>A couple of nitpicks is, its a little bit contrasty, tone it down next time and straighten the horizon a tiny bit.<br/> <br/>My pick for yellow.</td>', 'I always love reflections in the water especially of trees. Great job on seeing the beauty in the water. A couple of nitpicks is, its a little bit contrasty, tone it down next time and straighten the horizon a tiny bit. My pick for yellow.', '2020-03-25 00:39:04.000000', NULL, 1),
(7656334, 1246760, 114285, '<td valign="top">A beautiful rendition of a European city Im guessing, I like your processing. Its well composed and interesting to look at.<br/> <br/>This is the winner for me.</td>', 'A beautiful rendition of a European city Im guessing, I like your processing. Its well composed and interesting to look at. This is the winner for me.', '2020-03-25 01:12:40.000000', NULL, 1),
(7656337, 1246760, 15511, '<td valign="top">Easily the most interesting image in the challenge. Love the detail, the many things to look at, the sepia toning fits well.</td>', 'Easily the most interesting image in the challenge. Love the detail, the many things to look at, the sepia toning fits well.', '2020-03-25 01:42:14.000000', NULL, 1),
(7656355, 1246760, 42733, '<td valign="top">My favorite in this challenge.</td>', 'My favorite in this challenge.', '2020-03-25 07:04:29.000000', NULL, 1),
(7656356, 1246892, 42733, '<td valign="top">My pick for red in this challenge.</td>', 'My pick for red in this challenge.', '2020-03-25 07:04:38.000000', NULL, 1),
(7656357, 1246694, 42733, '<td valign="top">My pick for yellow in this challenge.</td>', 'My pick for yellow in this challenge.', '2020-03-25 07:04:52.000000', NULL, 1),
(7656359, 1246892, 135744, '<td valign="top">Absolutely gorgeous sky. I think I would have cropped more of the foreground out to let the sky have an even bigger presence.</td>', 'Absolutely gorgeous sky. I think I would have cropped more of the foreground out to let the sky have an even bigger presence.', '2020-03-25 07:19:41.000000', NULL, 1),
(7656360, 1246694, 135744, '<td valign="top">Those reflections are really nice especially with the ripple effect. I find the top section of the photo pulls this image down but I am not sure if cropping the photo to just the reflection would have worked.</td>', 'Those reflections are really nice especially with the ripple effect. I find the top section of the photo pulls this image down but I am not sure if cropping the photo to just the reflection would have worked.', '2020-03-25 07:22:21.000000', NULL, 1),
(7656361, 1246760, 135744, '<td valign="top">Looks like Amsterdam to me and I feel like i have been in this exact location on one of many visits to this fantastic city. You have captured the architecture, the water element, hussle and bustle nicely. I am not sure about the processing- to me Amsterdam is a very vibrant city so this goes against that feeling but to be fair it still looks good as a photograph.</td>', 'Looks like Amsterdam to me and I feel like i have been in this exact location on one of many visits to this fantastic city. You have captured the architecture, the water element, hussle and bustle nicely. I am not sure about the processing- to me Amsterdam is a very vibrant city so this goes against that feeling but to be fair it still looks good as a photograph.', '2020-03-25 07:28:53.000000', NULL, 1),
(7656362, 1246991, 135744, '<td valign="top">Oops I assume you didn''t want this photo on its side. It may have worked better in black and white.</td>', 'Oops I assume you didn''t want this photo on its side. It may have worked better in black and white.', '2020-03-25 07:29:26.000000', NULL, 1),
(7656363, 1246986, 135744, '<td valign="top">It doesn''t look like you were blessed with great light when you took this photo. I feel there is a lack of any real focal point and it does indeed look rather bleak.</td>', 'It doesn''t look like you were blessed with great light when you took this photo. I feel there is a lack of any real focal point and it does indeed look rather bleak.', '2020-03-25 07:30:45.000000', NULL, 1),
(7656364, 1246988, 135744, '<td valign="top">This looks like a pretty pond. I am not keen on the large shadow areaon the left hand side. The photo overall feels like it needs to pop a bit more. Looks like tricky light to photograph in - I really struggle to take photos with light like this.</td>', 'This looks like a pretty pond. I am not keen on the large shadow areaon the left hand side. The photo overall feels like it needs to pop a bit more. Looks like tricky light to photograph in - I really struggle to take photos with light like this.', '2020-03-25 07:32:25.000000', NULL, 1),
(7656381, 1246694, 50695, '<td valign="top">very pleasing abstract image. good patterns and colors</td>', 'very pleasing abstract image. good patterns and colors', '2020-03-25 10:48:53.000000', NULL, 1),
(7656383, 1246986, 50695, '<td valign="top">i like the bleak mood of this shot. it''s almost a romantic bleakness, like The Sorrows of Young Werther (or so I''m told)</td>', 'i like the bleak mood of this shot. it''s almost a romantic bleakness, like The Sorrows of Young Werther (or so I''m told)', '2020-03-25 10:58:40.000000', NULL, 1),
(7656384, 1246988, 50695, '<td valign="top">entry into what, one wonders....</td>', 'entry into what, one wonders....', '2020-03-25 10:58:59.000000', NULL, 1),
(7656385, 1246991, 50695, '<td valign="top">I like your dedication to landscape</td>', 'I like your dedication to landscape', '2020-03-25 10:59:25.000000', NULL, 1),
(7656387, 1246986, 86447, '<td valign="top">Love the natural framing of thee trees!   I wish there were more details in the black areas, for my taste.</td>', 'Love the natural framing of thee trees!   I wish there were more details in the black areas, for my taste.', '2020-03-25 11:12:50.000000', NULL, 1),
(7656388, 1246892, 86447, '<td valign="top">Lovely colors!   That sky is gorgeous!</td>', 'Lovely colors!   That sky is gorgeous!', '2020-03-25 11:13:14.000000', NULL, 1),
(7656389, 1246760, 86447, '<td valign="top">Fabulous!  My pick for the BLUE!  Processing is fun, too.</td>', 'Fabulous!  My pick for the BLUE!  Processing is fun, too.', '2020-03-25 11:13:39.000000', NULL, 1),
(7656390, 1246694, 86447, '<td valign="top">Fun image.  Beautiful reflections and composition.</td>', 'Fun image.  Beautiful reflections and composition.', '2020-03-25 11:14:08.000000', NULL, 1),
(7656392, 1246991, 86447, '<td valign="top">This is sideways.   Did you enter it straight from your cellphone.  It''s happened to me a couple of times.  Only vertical images, though.   Looked correct on my cellphone the whole time; only saw it was sideways when I went to a "real computer".   Darnsies.<br/> <br/>I suspect you''ll get at least a TT anyway!  :D</td>', 'This is sideways.   Did you enter it straight from your cellphone.  It''s happened to me a couple of times.  Only vertical images, though.   Looked correct on my cellphone the whole time; only saw it was sideways when I went to a "real computer".   Darnsies. I suspect you''ll get at least a TT anyway!  :D', '2020-03-25 11:19:08.000000', NULL, 1),
(7656393, 1246988, 86447, '<td valign="top">Lovely scene.   Seems a bit "flat" on the processing end to me, though.  Could be more vibrant or "Pop" a bit with a bit of curves adjustment, I think.</td>', 'Lovely scene.   Seems a bit "flat" on the processing end to me, though.  Could be more vibrant or "Pop" a bit with a bit of curves adjustment, I think.', '2020-03-25 11:19:49.000000', NULL, 1),
(7656398, 1246694, 163081, '<td valign="top">The composition looks fine. The reflection is making it interesting, but that''s about it. If it''s an attempt to make it artsy, there is a lack of order (straight lines vertically and horizontally). I also believe that this would look better in black and white and a more dramatic processing. In this challenge it is in my top 3.<br/>I will give you 2 extra points (6+2)for the purpose of this challenge and my Red Dragon Award <a href="https://www.dpchallenge.com/image.php?IMAGE_ID=1173262" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/160000-164999/163081/120/Copyrighted_Image_Reuse_Prohibited_1173262.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/160000-164999/163081/120/Copyrighted_Image_Reuse_Prohibited_1173262.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/160000-164999/163081/120/Copyrighted_Image_Reuse_Prohibited_1173262.jpg"/></a></td>', 'The composition looks fine. The reflection is making it interesting, but that''s about it. If it''s an attempt to make it artsy, there is a lack of order (straight lines vertically and horizontally). I also believe that this would look better in black and white and a more dramatic processing. In this challenge it is in my top 3.I will give you 2 extra points (6+2)for the purpose of this challenge and my Red Dragon Award ', '2020-03-25 13:01:48.000000', NULL, 1),
(7656400, 1246760, 163081, '<td valign="top">Clear winner, I actually love it. Composition looks great as is the point of view. You are definitely not a beginner. The people walking adds much to this picture. Processing is well thought and fits the scene. A 9 from me and my Blue Dragon Award<a href="https://www.dpchallenge.com/image.php?IMAGE_ID=1173261" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/160000-164999/163081/120/Copyrighted_Image_Reuse_Prohibited_1173261.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/160000-164999/163081/120/Copyrighted_Image_Reuse_Prohibited_1173261.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/160000-164999/163081/120/Copyrighted_Image_Reuse_Prohibited_1173261.jpg"/></a></td>', 'Clear winner, I actually love it. Composition looks great as is the point of view. You are definitely not a beginner. The people walking adds much to this picture. Processing is well thought and fits the scene. A 9 from me and my Blue Dragon Award', '2020-03-25 13:06:39.000000', NULL, 1),
(7656402, 1246988, 163081, '<td valign="top">First thing: your title. Every child has a name, this counts also for a picture. Remember that your picture is your child, and you should be proud of the given name/title. Second: some processing would make it a little less bland. <br/>Composition: You have nice sunlight coming into your picture, why not using this to get those tree shadows more prominent in you picture. I would have stand about 5 meters more to the right and get those dark and bright shadows. Don''t include the right side building. I will give you 2 extra point for the purpose of this challenge.</td>', 'First thing: your title. Every child has a name, this counts also for a picture. Remember that your picture is your child, and you should be proud of the given name/title. Second: some processing would make it a little less bland. Composition: You have nice sunlight coming into your picture, why not using this to get those tree shadows more prominent in you picture. I would have stand about 5 meters more to the right and get those dark and bright shadows. Don''t include the right side building. I will give you 2 extra point for the purpose of this challenge.', '2020-03-25 13:14:38.000000', NULL, 1),
(7656403, 1246892, 163081, '<td valign="top">Those clouds are AMAZING (a little over-saturated). The center of the image is way too dark and we can barely see what it is. With some processing this could easily be fixed. The foreground (grass) could improve this image a lot if processed better. It adds a wavy composition to the whole (brighter and with some dodge and burn to add depth in it). 2 extra point for the purpose of this challenge. An 8 from me (6+2) and my Yellow Dragon Award <a href="https://www.dpchallenge.com/image.php?IMAGE_ID=1173263" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/160000-164999/163081/120/Copyrighted_Image_Reuse_Prohibited_1173263.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/160000-164999/163081/120/Copyrighted_Image_Reuse_Prohibited_1173263.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/160000-164999/163081/120/Copyrighted_Image_Reuse_Prohibited_1173263.jpg"/></a></td>', 'Those clouds are AMAZING (a little over-saturated). The center of the image is way too dark and we can barely see what it is. With some processing this could easily be fixed. The foreground (grass) could improve this image a lot if processed better. It adds a wavy composition to the whole (brighter and with some dodge and burn to add depth in it). 2 extra point for the purpose of this challenge. An 8 from me (6+2) and my Yellow Dragon Award ', '2020-03-25 13:21:44.000000', NULL, 1),
(7656404, 1246991, 163081, '<td valign="top">I don''t think that rotating and image is a hard thing to do. Double check after entering. This will cost you many precious points. Another thing is that landscapes look better as panorama views.You have a beautiful sunlight and nice shadows, why not move around and try to add this touch into your composition. It looks uninteresting as a whole. 2 extra points for the purpose of the challenge (5+2)</td>', 'I don''t think that rotating and image is a hard thing to do. Double check after entering. This will cost you many precious points. Another thing is that landscapes look better as panorama views.You have a beautiful sunlight and nice shadows, why not move around and try to add this touch into your composition. It looks uninteresting as a whole. 2 extra points for the purpose of the challenge (5+2)', '2020-03-25 13:27:00.000000', NULL, 1),
(7656405, 1246986, 163081, '<td valign="top">I think that 10 years ago my smartphone took better quality than this shot. The blur doesn''t do you good here. Very uninteresting shot. Many flaws  that could easily be avoided. Nothing looks straight. Rule of thirds, sharpness, composition. The best part is the right side middle part, but then you need to crop out 95% out of your image. I will give you 2 extra point for the purpose of this challenge (4+2)</td>', 'I think that 10 years ago my smartphone took better quality than this shot. The blur doesn''t do you good here. Very uninteresting shot. Many flaws  that could easily be avoided. Nothing looks straight. Rule of thirds, sharpness, composition. The best part is the right side middle part, but then you need to crop out 95% out of your image. I will give you 2 extra point for the purpose of this challenge (4+2)', '2020-03-25 13:36:36.000000', NULL, 1),
(7656415, 1246694, 153275, '<td valign="top">I love the reflection of the trees in the water, especially from the sun-lit trees in the back. Nice found, a 7 from me</td>', 'I love the reflection of the trees in the water, especially from the sun-lit trees in the back. Nice found, a 7 from me', '2020-03-25 14:21:40.000000', NULL, 1),
(7656422, 1246694, 24454, '<td valign="top">Very artful!  I often see photos like this hanging on office walls.  Good job!</td>', 'Very artful!  I often see photos like this hanging on office walls.  Good job!', '2020-03-25 15:21:58.000000', NULL, 1),
(7656423, 1246760, 24454, '<td valign="top">Wow!  I love this! It looks like a vintage painting!  It''s only the first photo I''ve voting on, but it looks like a ribbon to me!  Good luck!<br/> <br/>PS... I''m back... just voted on all of them, and it''s for sure now that I think this one should be your first blue ribbon!  Nice job.</td>', 'Wow!  I love this! It looks like a vintage painting!  It''s only the first photo I''ve voting on, but it looks like a ribbon to me!  Good luck! PS... I''m back... just voted on all of them, and it''s for sure now that I think this one should be your first blue ribbon!  Nice job.', '2020-03-25 15:23:21.000000', NULL, 1),
(7656432, 1246760, 92512, '<td valign="top">Monotone makes this stand out, and creates the mood. Good job</td>', 'Monotone makes this stand out, and creates the mood. Good job', '2020-03-25 15:32:02.000000', NULL, 1),
(7656450, 1246892, 153275, '<td valign="top">I like the sky and the evening sun on the tree at the right side. The foreground is a little too dark in my opinion, I would have tried to increase the exposure of the dark tones in pp. 6</td>', 'I like the sky and the evening sun on the tree at the right side. The foreground is a little too dark in my opinion, I would have tried to increase the exposure of the dark tones in pp. 6', '2020-03-25 17:06:03.000000', NULL, 1),
(7656451, 1246991, 153275, '<td valign="top">An empty bench, a familiar sight these days of social distancing. I like the light of a sunny early-spring day, fresh and cold.<br/>The photo appears rotated, this seems to happen sometimes when an upright taken shot is entered from a phone.</td>', 'An empty bench, a familiar sight these days of social distancing. I like the light of a sunny early-spring day, fresh and cold.The photo appears rotated, this seems to happen sometimes when an upright taken shot is entered from a phone.', '2020-03-25 17:21:02.000000', NULL, 1),
(7656454, 1246986, 153275, '<td valign="top">The picture appears to be slightly out of focus. Also I would have cropped off the lower part with the dirty snow</td>', 'The picture appears to be slightly out of focus. Also I would have cropped off the lower part with the dirty snow', '2020-03-25 17:39:56.000000', NULL, 1),
(7656469, 1246694, 97225, '<td valign="top">This is a lovely photo as it is but when I scroll down to the top of the reflection, it is stunning and would have been my pick for blue if cropped to eliminate the shore. That is just my preference of course. Top two as it is.</td>', 'This is a lovely photo as it is but when I scroll down to the top of the reflection, it is stunning and would have been my pick for blue if cropped to eliminate the shore. That is just my preference of course. Top two as it is.', '2020-03-25 22:06:58.000000', NULL, 1),
(7656471, 1246892, 97225, '<td valign="top">Fabulous sky! To me the green looks too green - but then, I am an Australian and more used to brown grass. My pick for the yellow.</td>', 'Fabulous sky! To me the green looks too green - but then, I am an Australian and more used to brown grass. My pick for the yellow.', '2020-03-25 22:10:34.000000', NULL, 1),
(7656472, 1246988, 83313, '<td valign="top">Not doing much for me, I''m afraid. There are a lot of distracting elements around the edges of the scene that don''t add anything to the subject. Getting in closer to the pond and getting the lily pads and perhaps that tree refelction filling the frame would have been appealing to me.</td>', 'Not doing much for me, I''m afraid. There are a lot of distracting elements around the edges of the scene that don''t add anything to the subject. Getting in closer to the pond and getting the lily pads and perhaps that tree refelction filling the frame would have been appealing to me.', '2020-03-25 22:10:38.000000', NULL, 1),
(7656473, 1246892, 83313, '<td valign="top">Lovely clouds. The trees at the right and left are trying to draw my eyes away from it, though.</td>', 'Lovely clouds. The trees at the right and left are trying to draw my eyes away from it, though.', '2020-03-25 22:11:44.000000', NULL, 1),
(7656474, 1246694, 83313, '<td valign="top">Wonderful reflection. Just the reflection on it''s own would have made a stronger impact on me, however. The small bit of shore at the top draws my eyes upward to the least interesting part of the image.</td>', 'Wonderful reflection. Just the reflection on it''s own would have made a stronger impact on me, however. The small bit of shore at the top draws my eyes upward to the least interesting part of the image.', '2020-03-25 22:14:00.000000', NULL, 1),
(7656475, 1246991, 97225, '<td valign="top">Why the sideways presentation?<br/>Sorry, from what I just read in the forums that can happen inadvertently, so I''ll just enjoy it with my head kinked sideways. It looks like it would be a pleasant place to sit in normal times. As it is you have captured the desolation/desertion well.</td>', 'Why the sideways presentation?Sorry, from what I just read in the forums that can happen inadvertently, so I''ll just enjoy it with my head kinked sideways. It looks like it would be a pleasant place to sit in normal times. As it is you have captured the desolation/desertion well.', '2020-03-25 22:14:33.000000', NULL, 1),
(7656476, 1246986, 83313, '<td valign="top">Not much here to entertain my eyes, I''m afraid. Perhaps there were some interesting patterns in the snow and ice you might have focused on.</td>', 'Not much here to entertain my eyes, I''m afraid. Perhaps there were some interesting patterns in the snow and ice you might have focused on.', '2020-03-25 22:16:10.000000', NULL, 1),
(7656477, 1246991, 83313, '<td valign="top">Wondering if the sideways was intentional...</td>', 'Wondering if the sideways was intentional...', '2020-03-25 22:16:47.000000', NULL, 1),
(7656478, 1246760, 97225, '<td valign="top">A lovely scene with plenty to keep me interested and nice leading lines to encourage my eye to move through. Top two.</td>', 'A lovely scene with plenty to keep me interested and nice leading lines to encourage my eye to move through. Top two.', '2020-03-25 22:17:08.000000', NULL, 1),
(7656479, 1246760, 83313, '<td valign="top">Pleasing scene, but comes off to me a bit flat. Perhaps some stronger contrast or selective editing to bring out some of those wonderful details?</td>', 'Pleasing scene, but comes off to me a bit flat. Perhaps some stronger contrast or selective editing to bring out some of those wonderful details?', '2020-03-25 22:19:08.000000', NULL, 1),
(7656481, 1246986, 3306, '<td valign="top">Im not sure if you matched the title to the picture or visa versa. You are right that the picture is bleak, drab and not very appealing. The good thing is that you realize it. Sorry to be critical but the purpose of this challenge was to help you improve. If you are looking to improve on this perspective I would suggest taking the picture at a different time of day when there is more color in the sky and more definition in the landscape. I would recommend using a tripod to allow you to get a sharper image and a greater depth of field. Also the image needs to be rotated slightly to get it to horizontal. Also to get some interest you might want to wait around to see if some birds show up in the field of vision.</td>', 'Im not sure if you matched the title to the picture or visa versa. You are right that the picture is bleak, drab and not very appealing. The good thing is that you realize it. Sorry to be critical but the purpose of this challenge was to help you improve. If you are looking to improve on this perspective I would suggest taking the picture at a different time of day when there is more color in the sky and more definition in the landscape. I would recommend using a tripod to allow you to get a sharper image and a greater depth of field. Also the image needs to be rotated slightly to get it to horizontal. Also to get some interest you might want to wait around to see if some birds show up in the field of vision.', '2020-03-25 22:36:30.000000', NULL, 1),
(7656497, 1246694, 20608, '<td valign="top">I think if you cropped the top bit out of the shot and left just the reflection, then turned the image upside down you would have a great chance of the blue ribbon, the gold &amp; blue tones rippling together makes a much better image than a bunch of tree bottoms with no focal point.</td>', 'I think if you cropped the top bit out of the shot and left just the reflection, then turned the image upside down you would have a great chance of the blue ribbon, the gold & blue tones rippling together makes a much better image than a bunch of tree bottoms with no focal point.', '2020-03-26 04:37:59.000000', NULL, 1),
(7656498, 1246991, 20608, '<td valign="top">I''m sure you will finish last, congratulations</td>', 'I''m sure you will finish last, congratulations', '2020-03-26 04:38:30.000000', NULL, 1),
(7656499, 1246760, 20608, '<td valign="top">Best of the 6 in my opinion</td>', 'Best of the 6 in my opinion', '2020-03-26 04:39:14.000000', NULL, 1),
(7656500, 1246892, 20608, '<td valign="top">My pick for 2nd place, if you had lifted the shadow detail up a tad you would of improved this shot, also a tighter crop turns this into a landscape instead of a skyscape.</td>', 'My pick for 2nd place, if you had lifted the shadow detail up a tad you would of improved this shot, also a tighter crop turns this into a landscape instead of a skyscape.', '2020-03-26 04:40:52.000000', NULL, 1),
(7656502, 1246760, 60581, '<td valign="top">you are my #1</td>', 'you are my #1', '2020-03-26 08:14:51.000000', NULL, 1),
(7656503, 1246694, 60581, '<td valign="top">you are my #2</td>', 'you are my #2', '2020-03-26 08:14:56.000000', NULL, 1),
(7656504, 1246892, 60581, '<td valign="top">you are my #3</td>', 'you are my #3', '2020-03-26 08:15:05.000000', NULL, 1),
