(7656978, 1246991, 28742, '<td valign="top">I feel compelled to give this the Shoehorn award. ;-)</td>', 'I feel compelled to give this the Shoehorn award. ;-)', '2020-03-31 04:12:03.000000', NULL, 1),
(7657050, 1246986, 83313, '<td valign="top">Thanks for the explanation in your notes and in the forums during voting (though I could only guess which one was yours, I was right). I voted on these entries as I would have voted on any other challenge, but I left comments on every one of them explaining my vote. Sometimes the viewer won''t or can''t see what the photographer is trying to illustrate and such was the case here.</td>', 'Thanks for the explanation in your notes and in the forums during voting (though I could only guess which one was yours, I was right). I voted on these entries as I would have voted on any other challenge, but I left comments on every one of them explaining my vote. Sometimes the viewer won''t or can''t see what the photographer is trying to illustrate and such was the case here.', '2020-04-01 01:59:55.000000', NULL, 0),
(7657055, 1246760, 114285, '<td valign="top">Congratulations, it was the best of the lot, and probably would of fared well in any landscape challenge. Great score too!!</td>', 'Congratulations, it was the best of the lot, and probably would of fared well in any landscape challenge. Great score too!!', '2020-04-01 03:03:40.000000', NULL, 0),
(7657063, 1246986, 114285, '<td valign="top">I had a feeling this was yours. Reading your notes I still think you could of done better - still if there were more entries would you have tried harder?? Just wondering.</td>', 'I had a feeling this was yours. Reading your notes I still think you could of done better - still if there were more entries would you have tried harder?? Just wondering.', '2020-04-01 05:08:51.000000', NULL, 0),
(7657065, 1246991, 114285, '<td valign="top">I see from your location you live in Hamilton Ontario. Under one hour to Niagra Falls, now that would of made a sensational landscape!</td>', 'I see from your location you live in Hamilton Ontario. Under one hour to Niagra Falls, now that would of made a sensational landscape!', '2020-04-01 05:14:39.000000', NULL, 0),
(7657066, 1246760, 135744, '<td valign="top">Congratulations on your first ribbon. Apologies for thinking it was Amsterdam. I really like the colour version. Thank you for sharing.</td>', 'Congratulations on your first ribbon. Apologies for thinking it was Amsterdam. I really like the colour version. Thank you for sharing.', '2020-04-01 05:26:52.000000', NULL, 0),
(7657067, 1246694, 135744, '<td valign="top">Congrats on the red!</td>', 'Congrats on the red!', '2020-04-01 05:27:07.000000', NULL, 0),
(7657068, 1246892, 135744, '<td valign="top">Congrats on your first ribbon!</td>', 'Congrats on your first ribbon!', '2020-04-01 05:27:30.000000', NULL, 0),
(7657069, 1246892, 135744, '<td valign="top">Congrats on your first ribbon!</td>', 'Congrats on your first ribbon!', '2020-04-01 05:27:31.000000', NULL, 0),
